#define LIFT_RET(pop_bytes) do { lift_return(cpu, (uint32_t)(pop_bytes), stop_address); return; } while (0)
#define LIFT_ADD(left_expression, right_expression, carry_expression, width, writeback) do { uint64_t left = (uint64_t)(left_expression); uint64_t right = (uint64_t)(right_expression); uint64_t carry = (carry_expression); uint64_t result = left + right + carry; lift_flags_add(cpu, left, right, carry, result, (width)); writeback; } while (0)
#define LIFT_SUB(left_expression, right_expression, borrow_expression, width, writeback) do { uint64_t left = (uint64_t)(left_expression); uint64_t right = (uint64_t)(right_expression); uint64_t borrow = (borrow_expression); uint64_t result = left - right - borrow; lift_flags_sub(cpu, left, right, borrow, result, (width)); writeback; } while (0)
#define LIFT_SUB_FLAGS(left_expression, right_expression, borrow_expression, width) do { uint64_t left = (uint64_t)(left_expression); uint64_t right = (uint64_t)(right_expression); uint64_t borrow = (borrow_expression); uint64_t result = left - right - borrow; lift_flags_sub(cpu, left, right, borrow, result, (width)); } while (0)
#define LIFT_CMP(left_expression, right_expression, width) LIFT_SUB_FLAGS(left_expression, right_expression, 0u, width)
#define LIFT_INC(left_expression, width, writeback) do { uint64_t left = (uint64_t)(left_expression); uint32_t saved_carry = cpu->eflags & LIFT_FLAG_CF; uint64_t result = left + 1u; lift_flags_add(cpu, left, 1u, 0u, result, (width)); cpu->eflags = (cpu->eflags & ~LIFT_FLAG_CF) | saved_carry; writeback; } while (0)
#define LIFT_DEC(left_expression, width, writeback) do { uint64_t left = (uint64_t)(left_expression); uint32_t saved_carry = cpu->eflags & LIFT_FLAG_CF; uint64_t result = left - 1u; lift_flags_sub(cpu, left, 1u, 0u, result, (width)); cpu->eflags = (cpu->eflags & ~LIFT_FLAG_CF) | saved_carry; writeback; } while (0)
#define LIFT_LOGIC(left_expression, right_expression, operation, width, writeback) do { uint64_t left = (uint64_t)(left_expression); uint64_t right = (uint64_t)(right_expression); uint64_t result = left operation right; lift_flags_logic(cpu, result, (width)); writeback; } while (0)
#define LIFT_LOGIC_FLAGS(left_expression, right_expression, operation, width) do { uint64_t left = (uint64_t)(left_expression); uint64_t right = (uint64_t)(right_expression); uint64_t result = left operation right; lift_flags_logic(cpu, result, (width)); } while (0)
#define LIFT_TEST(value_expression, width) LIFT_LOGIC_FLAGS(value_expression, value_expression, &, width)
#define LIFT_ZERO(target, width) LIFT_LOGIC(target, target, ^, width, target = (uint32_t)(result);)
#define LIFT_NEG(value_expression, width, writeback) do { uint64_t value = (uint64_t)(value_expression); uint64_t result = 0u - value; lift_flags_sub(cpu, 0u, value, 0u, result, (width)); cpu->eflags = (cpu->eflags & ~LIFT_FLAG_CF) | ((value != 0u) ? LIFT_FLAG_CF : 0u); writeback; } while (0)
#define LIFT_IMUL32(target, source) do { int64_t result = (int64_t)(int32_t)(target) * (int64_t)(int32_t)(source); target = (uint32_t)((uint64_t)result); int64_t truncated = (int64_t)(int32_t)result; uint32_t overflow = truncated != result; cpu->eflags = (cpu->eflags & ~LIFT_FLAG_CF) | ((overflow != 0u) ? LIFT_FLAG_CF : 0u); cpu->eflags = (cpu->eflags & ~LIFT_FLAG_OF) | ((overflow != 0u) ? LIFT_FLAG_OF : 0u); } while (0)
#define LIFT_SP_ADD(value) LIFT_ADD(cpu->esp, value, 0u, 32u, cpu->esp = (uint32_t)(result);)
